const toast=document.getElementById('actionToast');let toastTimer;
function notify(message,type='ok'){if(!toast)return;toast.textContent=message;toast.dataset.type=type;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3500)}
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const date=value=>{if(!value)return'—';const raw=String(value),ymd=raw.match(/^(\d{4})-(\d{2})-(\d{2})/);if(ymd&&!raw.includes('T'))return`${Number(ymd[3])}/${Number(ymd[2])}/${ymd[1]}`;const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'—':`${parsed.getDate()}/${parsed.getMonth()+1}/${parsed.getFullYear()}`};
const statusLabel={pending:'بانتظار الموافقة',active:'نشط',blocked:'محظور',rejected:'مرفوض',awaiting_payment:'بانتظار الدفع',expired:'منتهي',cancelled:'ملغي'};
let adminStore=null,currentProfile=null,memberFilter='all',memberHealth=null,memberWorkoutLogs=[],memberMealLogs=[],currentMemberProgram=null;

function addNotificationCenter(){const top=document.querySelector('.top');if(!top)return;const bell=document.createElement('button');bell.className='notification-bell';bell.type='button';bell.innerHTML='<span>🔔</span><b>0</b>';bell.setAttribute('aria-label','التنبيهات');const panel=document.createElement('section');panel.className='notification-panel';panel.innerHTML='<header><strong>التنبيهات</strong><button type="button">تحديد الكل كمقروء</button></header><div class="loading">جاري التحميل…</div>';document.body.append(panel);top.querySelector('.top-actions')?.prepend(bell);bell.onclick=()=>panel.classList.toggle('open');document.addEventListener('click',e=>{if(!panel.contains(e.target)&&!bell.contains(e.target))panel.classList.remove('open')});panel.querySelector('header button').onclick=()=>{panel.querySelectorAll('.unread').forEach(x=>x.classList.remove('unread'));bell.querySelector('b')?.remove()};return{bell,panel}}
const notificationUI=addNotificationCenter();
async function loadNotifications(){const notices=await StrongGymAPI.notifications().catch(()=>[]);if(!notificationUI)return;const {bell,panel}=notificationUI;panel.querySelectorAll('article,.loading').forEach(x=>x.remove());notices.forEach(item=>{const row=document.createElement('article');if(!item.read_at)row.className='unread';row.innerHTML=`<i></i><div><b>${esc(item.title_ar)}</b><p>${esc(item.body_ar)}</p><small>${date(item.created_at)}</small></div>`;row.onclick=()=>{if(!item.read_at){StrongGymAPI.markNotificationRead(item.id);row.classList.remove('unread')}};panel.append(row)});if(!notices.length)panel.insertAdjacentHTML('beforeend','<div class="empty-state">لا توجد تنبيهات.</div>');const count=notices.filter(x=>!x.read_at).length,badge=bell.querySelector('b');if(count)badge.textContent=count;else badge?.remove()}

function goView(name,push=true){const target=document.querySelector(`[data-view="${name}"]`);if(!target)return;document.querySelectorAll('.admin-view').forEach(v=>v.classList.toggle('active',v===target));document.querySelectorAll('[data-view-link]').forEach(a=>a.classList.toggle('active',a.dataset.viewLink===name));const titles={overview:'لوحة الإدارة',members:'إدارة المشتركين',payments:'الاشتراكات والدفعات',measurements:'سجل القياسات',plans:'التمارين والتغذية',settings:'الإعدادات'};document.getElementById('pageTitle').textContent=titles[name]||'لوحة الإدارة';if(push&&location.hash!==`#${name}`)history.pushState(null,'',`#${name}`);side?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view-link],[data-go]').forEach(el=>el.onclick=e=>{e.preventDefault();goView(el.dataset.viewLink||el.dataset.go)});window.addEventListener('hashchange',()=>goView(location.hash.slice(1)||'overview',false));

function memberSubscription(id){return adminStore.subscriptions.find(s=>s.member_id===id&&s.status==='active')||adminStore.subscriptions.find(s=>s.member_id===id&&s.status==='awaiting_payment')||adminStore.subscriptions.find(s=>s.member_id===id)}
function planOf(id){return adminStore.plans.find(p=>String(p.id)===String(id))}
function renderOverview(){const now=new Date(),month=now.getMonth(),year=now.getFullYear(),memberIds=new Set(adminStore.profiles.map(p=>p.id)),memberSubs=adminStore.subscriptions.filter(s=>memberIds.has(s.member_id)),active=adminStore.profiles.filter(p=>p.status==='active').length,pending=adminStore.profiles.filter(p=>p.status==='pending').length,revenue=adminStore.payments.filter(p=>{const d=new Date(p.paid_at);return d.getMonth()===month&&d.getFullYear()===year}).reduce((s,p)=>s+Number(p.amount_ils),0),soon=memberSubs.filter(s=>s.status==='active'&&s.ends_on&&new Date(s.ends_on)>=new Date(now.toDateString())&&new Date(s.ends_on)<=new Date(Date.now()+7*864e5)).length;document.querySelector('[data-stat="members"]').textContent=active;document.querySelector('[data-stat="revenue"]').textContent=`${revenue.toLocaleString('ar-PS')} ₪`;document.querySelector('[data-stat="pending"]').textContent=pending;document.querySelector('[data-stat="expiring"]').textContent=soon;document.getElementById('monthRevenue').textContent=`${revenue.toLocaleString('ar-PS')} ₪`;document.getElementById('awaitingCount').textContent=memberSubs.filter(s=>s.status==='awaiting_payment').length;document.getElementById('activeSubCount').textContent=memberSubs.filter(s=>s.status==='active').length;renderApprovals()}
function renderApprovals(){const list=document.getElementById('approvalList');if(!list)return;const pending=adminStore.profiles.filter(p=>p.status==='pending');list.innerHTML=pending.length?'':'<div class="empty-state">لا توجد طلبات تسجيل جديدة.</div>';pending.slice(0,5).forEach(member=>{const row=document.createElement('div');row.className='approval';row.dataset.gender=member.gender==='female'?'women':'men';row.innerHTML=`<div class="avatar">${esc(member.full_name.charAt(0))}</div><div><b>${esc(member.full_name)}</b><small>${member.gender==='female'?'نساء':'رجال'} · ${esc(member.email)}</small></div><div class="approval-actions"><button class="icon-btn accept">✓</button><button class="icon-btn decline">×</button></div>`;row.querySelector('.accept').onclick=()=>changeStatus(member.id,'active');row.querySelector('.decline').onclick=()=>changeStatus(member.id,'rejected');list.append(row)})}
function renderMembers(){const body=document.getElementById('membersTable'),query=(document.getElementById('memberSearch')?.value||'').toLowerCase();let rows=adminStore.profiles.filter(p=>(memberFilter==='all'||p.status===memberFilter)&&`${p.full_name} ${p.email} ${p.whatsapp_e164||''}`.toLowerCase().includes(query));body.innerHTML=rows.length?'':'<tr><td colspan="7" class="empty-state">لا توجد نتائج.</td></tr>';rows.forEach(p=>{const sub=memberSubscription(p.id),plan=sub&&planOf(sub.plan_id),tr=document.createElement('tr');tr.dataset.gender=p.gender==='female'?'women':'men';tr.innerHTML=`<td><b>${esc(p.full_name)}</b><small class="cell-sub">${esc(p.email)}</small></td><td>${p.gender==='female'?'نساء':'رجال'}</td><td dir="ltr">${esc(p.whatsapp_e164||'—')}</td><td>${esc(plan?.name_ar||'—')}</td><td>${date(sub?.ends_on)}</td><td><span class="badge ${p.status}">${statusLabel[p.status]||p.status}</span></td><td class="row-actions"></td>`;const actions=tr.querySelector('.row-actions');if(p.status==='pending'){actions.append(actionButton('قبول','accept',()=>changeStatus(p.id,'active')),actionButton('رفض','decline',()=>changeStatus(p.id,'rejected')))}else if(p.status==='active')actions.append(actionButton('حظر','decline',()=>changeStatus(p.id,'blocked')));else actions.append(actionButton('تفعيل','accept',()=>changeStatus(p.id,'active')));body.append(tr)})}
function actionButton(label,cls,handler){const b=document.createElement('button');b.className=`mini-action ${cls}`;b.textContent=label;b.onclick=handler;return b}
async function changeStatus(id,status){if(currentProfile.role!=='manager'){notify('تغيير حالة الحساب متاح للمدير فقط','error');return}try{await StrongGymAPI.setMemberStatus(id,status);const member=adminStore.profiles.find(p=>p.id===id);member.status=status;renderAll();notify(status==='active'?'تم تفعيل الحساب':'تم تحديث حالة الحساب')}catch(e){notify(e.message,'error')}}
function renderPayments(){const body=document.getElementById('paymentsTable');body.innerHTML='';adminStore.subscriptions.forEach(s=>{const member=adminStore.profiles.find(p=>p.id===s.member_id),plan=planOf(s.plan_id),payment=adminStore.payments.find(p=>p.subscription_id===s.id);if(!member)return;body.insertAdjacentHTML('beforeend',`<tr><td>${esc(member.full_name)}</td><td>${esc(plan?.name_ar||'—')}</td><td>${payment?`${payment.amount_ils} ₪`:'—'}</td><td>${date(payment?.paid_at)}</td><td>${date(s.starts_on)}</td><td>${date(s.ends_on)}</td><td><span class="badge ${s.status}">${statusLabel[s.status]||s.status}</span></td></tr>`) });if(!body.children.length)body.innerHTML='<tr><td colspan="7" class="empty-state">لا توجد اشتراكات.</td></tr>'}
function renderMeasurements(){const body=document.getElementById('measurementsTable');body.innerHTML='';adminStore.measurements.forEach(m=>{const member=adminStore.profiles.find(p=>p.id===m.member_id);body.insertAdjacentHTML('beforeend',`<tr><td>${esc(member?.full_name||'—')}</td><td>${date(m.recorded_at)}</td><td>${m.height_cm} سم</td><td><b>${m.weight_kg} كغ</b></td><td>${m.waist_cm||'—'}</td><td>${m.chest_cm||'—'}</td><td>${m.hips_cm||'—'}</td><td>${m.arm_cm||'—'}</td><td>${m.thigh_cm||'—'}</td></tr>`) });if(!body.children.length)body.innerHTML='<tr><td colspan="9" class="empty-state">لم تُسجّل قياسات بعد. اضغط «تسجيل قياسات» للبدء.</td></tr>'}
function renderPrograms(){const list=document.getElementById('programsList');if(!list)return;const programs=adminStore.programs.filter(p=>p.active);list.innerHTML=programs.length?'':'<div class="empty-state">لا توجد برامج نشطة بعد.</div>';programs.forEach(p=>{const member=adminStore.profiles.find(m=>m.id===p.member_id),goal={weight_loss:'نزول وزن',muscle_gain:'زيادة عضل',fitness:'لياقة عامة'}[p.goal];list.insertAdjacentHTML('beforeend',`<div class="program-row"><div><b>${esc(member?.full_name||'—')}</b><small>${goal} · ${p.training_days} أيام أسبوعيًا</small></div><div><strong>${p.daily_calories}</strong><small>سعرة يوميًا</small></div><div><strong>${p.protein_g}غ</strong><small>بروتين</small></div><div><strong>${p.water_liters}L</strong><small>ماء</small></div></div>`)})}
function fillForms(){const ps=document.getElementById('paymentSubscription'),ms=document.getElementById('measurementMember'),program=document.getElementById('programMember');ps.innerHTML='';adminStore.subscriptions.filter(s=>s.status==='awaiting_payment').forEach(s=>{const member=adminStore.profiles.find(p=>p.id===s.member_id),plan=planOf(s.plan_id);if(member&&member.status==='active')ps.insertAdjacentHTML('beforeend',`<option value="${s.id}" data-amount="${plan.price_ils}">${esc(member.full_name)} — ${esc(plan.name_ar)} (${plan.price_ils} ₪)</option>`)});if(!ps.children.length)ps.innerHTML='<option value="">لا توجد اشتراكات جاهزة للدفع</option>';const memberOptions='<option value="">اختر المشترك</option>'+adminStore.profiles.filter(p=>p.status==='active').map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('');ms.innerHTML=memberOptions;if(program)program.innerHTML=memberOptions;syncPaymentAmount()}
function renderAll(){renderOverview();renderMembers();renderPayments();renderMeasurements();renderPrograms();fillForms();document.getElementById('lastSync').textContent=new Date().toLocaleTimeString('ar-PS',{hour:'2-digit',minute:'2-digit'})}

// Weekly manager export: a readable JSON backup that can also be opened as text.
const backupStorageKey='strong_gym_last_backup';
function updateBackupStatus(){const label=document.getElementById('lastBackupLabel');if(!label)return;const last=Number(localStorage.getItem(backupStorageKey)||0);label.textContent=last?`آخر نسخة من هذا الجهاز: ${new Intl.DateTimeFormat('ar-PS',{dateStyle:'long',timeStyle:'short'}).format(new Date(last))}`:'لم يتم تنزيل نسخة من هذا الجهاز بعد.'}
function backupFileName(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return`strong-gym-backup-${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}.json`}
function downloadAdminBackup(){if(!adminStore)return notify('لم تكتمل مزامنة البيانات بعد','error');const payload={format:'strong-gym-backup',version:1,created_at:new Date().toISOString(),created_by:{id:currentProfile?.id||null,name:currentProfile?.full_name||null},counts:Object.fromEntries(Object.entries(adminStore).map(([key,value])=>[key,Array.isArray(value)?value.length:0])),data:adminStore};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=backupFileName();document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);localStorage.setItem(backupStorageKey,String(Date.now()));updateBackupStatus();notify('تم تنزيل النسخة الاحتياطية. احفظها في Drive أو على فلاشة.')}
document.getElementById('downloadBackup')?.addEventListener('click',downloadAdminBackup);

function buildProgram(memberId,goal,days,notes){const member=adminStore.profiles.find(p=>p.id===memberId),latest=adminStore.measurements.find(m=>m.member_id===memberId),weight=Number(latest?.weight_kg||70),height=Number(latest?.height_cm||165),base=10*weight+6.25*height-5*25+(member?.gender==='male'?5:-161),calories=Math.max(1200,Math.round((base*1.45+(goal==='muscle_gain'?250:goal==='weight_loss'?-350:0))/50)*50),protein=Math.round(weight*(goal==='muscle_gain'?2:1.7)),fats=Math.round(weight*.8),carbs=Math.max(80,Math.round((calories-protein*4-fats*9)/4)),water=Math.min(8,Math.max(1.5,Math.round(weight*.035*10)/10));const library={weight_loss:[['اليوم 1','جسم كامل + مشي',['Squat 3×12','Chest Press 3×12','Lat Pulldown 3×12','مشي سريع 20 دقيقة']],['اليوم 2','جزء سفلي',['Leg Press 4×12','Hip Thrust 4×12','Leg Curl 3×15','مشي 15 دقيقة']],['اليوم 3','جزء علوي',['Shoulder Press 3×12','Seated Row 3×12','Biceps Curl 3×15','دراجة 20 دقيقة']]],muscle_gain:[['اليوم 1','Push',['Bench Press 4×8','Shoulder Press 4×10','Chest Fly 3×12','Triceps Pushdown 3×12']],['اليوم 2','Pull',['Lat Pulldown 4×10','Seated Row 4×10','Face Pull 3×15','Biceps Curl 3×12']],['اليوم 3','Legs',['Squat 4×8','Leg Press 4×10','Hip Thrust 4×10','Leg Curl 3×12']]],fitness:[['اليوم 1','جسم كامل',['Goblet Squat 3×12','Push Up 3×10','Cable Row 3×12','Plank 3×30 ثانية']],['اليوم 2','لياقة وحركة',['مشي سريع 25 دقيقة','Lunges 3×10','Shoulder Press 3×12','تمارين مرونة 10 دقائق']],['اليوم 3','قوة خفيفة',['Leg Press 3×12','Chest Press 3×12','Lat Pulldown 3×12','دراجة 15 دقيقة']]]};const workout=[];for(let i=0;i<Number(days);i++){const template=library[goal][i%3];workout.push({day:`اليوم ${i+1}`,focus:template[1],exercises:template[2]})}const meals=[{name:'الإفطار',items:'بيض أو لبنة + خبز كامل + خضار'},{name:'وجبة خفيفة',items:'فاكهة + حفنة مكسرات'},{name:'الغداء',items:'مصدر بروتين + أرز أو بطاطا + سلطة'},{name:'بعد التمرين',items:'زبادي أو حليب + موز'},{name:'العشاء',items:'تونة أو جبنة قليلة الدسم + خضار'}];return{member_id:memberId,goal,training_days:Number(days),daily_calories:calories,protein_g:protein,carbs_g:carbs,fats_g:fats,water_liters:water,workout_plan:workout,meal_plan:meals,notes:notes||null,active:true}}
function exerciseVisual(focus,index){const value=String(focus||'').toLowerCase();if(/leg|سفلي|أرجل|ارجل|squat/.test(value))return['assets/exercises/legs-training.png','تمارين الأرجل'];if(/pull|سحب|ظهر|علوي|row/.test(value))return['assets/exercises/pull-training.png','تمارين السحب'];if(/push|دفع|صدر|shoulder/.test(value))return['assets/exercises/push-training.png','تمارين الدفع'];return index%3===1?['assets/exercises/pull-training.png','تمارين السحب']:index%3===2?['assets/exercises/legs-training.png','تمارين الأرجل']:['assets/exercises/push-training.png','تمارين الدفع']}
function exerciseThumb(name){const value=String(name||'').toLowerCase(),rules=[[/goblet/,15],[/bench press/,11],[/chest press/,1],[/chest fly/,12],[/lat pulldown/,2],[/leg press/,4],[/hip thrust/,5],[/leg curl/,6],[/shoulder press/,7],[/seated row/,8],[/cable row/,17],[/biceps/,9],[/triceps/,13],[/face pull/,14],[/push.?up/,16],[/plank/,18],[/lunge/,19],[/squat/,0],[/مشي|walk/,3],[/دراجة|bicycle|bike/,10],[/مرونة|stretch|mobility/,20],[/جسم كامل|full.?body/,21],[/قوة خفيفة|light strength/,22],[/cardio|لياقة/,23]],match=rules.find(([pattern])=>pattern.test(value)),index=match?match[1]:24,row=Math.floor(index/5),col=index%5;return`--thumb-x:${col*25}%;--thumb-y:${row*25}%`}
function workoutType(name){const value=String(name||'').toLowerCase();return /مشي|دراجة|cardio|walk|bike|bicycle/.test(value)?'cardio':/مرونة|stretch|mobility/.test(value)?'mobility':'strength'}
function latestExerciseLog(name){return memberWorkoutLogs.filter(log=>log.exercise_name===name&&log.completed).sort((a,b)=>String(b.session_date).localeCompare(String(a.session_date))||String(b.updated_at).localeCompare(String(a.updated_at)))[0]}
function progressionAdvice(name,type){const log=latestExerciseLog(name);if(!log)return'سجّل أول أداء لنحدد هدفك القادم';if(type==='strength'){const weight=Number(log.weight_kg||0),step=log.difficulty==='easy'?Math.max(2.5,weight*.05):log.difficulty==='good'?2.5:0,next=Math.round((weight+step)*2)/2;return log.difficulty==='hard'?`ثبّت على ${weight||'نفس'} كغ وركّز على الأداء`:`الهدف القادم: ${next||2.5} كغ · ${log.reps||'نفس'} تكرار`}const minutes=Number(log.duration_minutes||0),extra=log.difficulty==='hard'?0:type==='cardio'?5:2;return log.difficulty==='hard'?`ثبّت على ${minutes} دقيقة حتى يصبح الأداء أسهل`:`الهدف القادم: ${minutes+extra} دقيقة`}
function weeklyReview(program){const since=new Date(Date.now()-6*864e5).toISOString().slice(0,10),week=memberWorkoutLogs.filter(log=>log.completed&&log.session_date>=since),groups={};week.forEach(log=>(groups[log.exercise_name]??=[]).push(log));const suggestions=Object.entries(groups).map(([name,logs])=>{const hard=logs.filter(x=>x.difficulty==='hard').length,easy=logs.filter(x=>x.difficulty==='easy').length,type=workoutType(name);if(hard>=2)return`بدّل أو خفّف ${name}: ${type==='strength'?'نزّل الحمل 10% أو استخدم نسخة أسهل':'اخفض المدة واستبدله بخيار أخف'}`;if(easy>=1)return`${name}: ${type==='strength'?'زد الوزن 2.5–5% مع نفس التكرارات':`زد المدة ${type==='cardio'?5:2} دقائق`}`;return logs.length?`${name}: أضف 1–2 تكرار مع تثبيت الأداء`:null}).filter(Boolean).slice(0,4);if(!suggestions.length)suggestions.push(`استمر على الخطة الحالية وسجّل جلستين على الأقل لتفعيل اقتراحات ${program.goal==='muscle_gain'?'زيادة القوة':'التقدّم'}.`);return`<div class="weekly-review"><header><div><span>مراجعة أسبوعية ذكية</span><b>تعديلات الخطة المقترحة</b></div><em>حسب أدائك وهدفك</em></header>${suggestions.map((s,i)=>`<p><i>${i+1}</i>${esc(s)}</p>`).join('')}</div>`}
function trackingOverview(program){const since=new Date(Date.now()-6*864e5).toISOString().slice(0,10),week=memberWorkoutLogs.filter(log=>log.completed&&log.session_date>=since),sessions=new Set(week.map(log=>log.session_date)).size,total=program.workout_plan.reduce((sum,day)=>sum+day.exercises.length,0),completedToday=memberWorkoutLogs.filter(log=>log.completed&&log.session_date===new Date().toISOString().slice(0,10)).length,percent=Math.min(100,Math.round(completedToday/Math.max(1,total/program.training_days)*100));return`<div class="tracking-overview"><div><span>هذا الأسبوع</span><b>${sessions}<small> / ${program.training_days} جلسات</small></b></div><div><span>إنجاز اليوم</span><b>${percent}%</b></div><div class="tracking-bar"><i style="width:${percent}%"></i></div><p>${sessions>=program.training_days?'أسبوع مكتمل — استمر على هذا الأداء 💪':sessions?'تقدّم ممتاز، أكمل الجلسات المتبقية.':'ابدأ أول جلسة وسجّل أداءك لكل تمرين.'}</p></div>${weeklyReview(program)}`}
function trackingControls(exercise,dayIndex){const type=workoutType(exercise),last=latestExerciseLog(exercise),today=new Date().toISOString().slice(0,10),current=memberWorkoutLogs.find(log=>log.exercise_name===exercise&&Number(log.day_index)===dayIndex&&log.session_date===today),done=current?.completed?' completed':'',fields=type==='strength'?`<label>الوزن<input name="weight" type="number" min="0" max="500" step="0.5" value="${current?.weight_kg??last?.weight_kg??''}" placeholder="كغ"></label><label>التكرارات<input name="reps" type="number" min="0" max="1000" value="${current?.reps??last?.reps??''}" placeholder="عدد"></label>`:`<label>المدة<input name="duration" type="number" min="1" max="600" value="${current?.duration_minutes??last?.duration_minutes??''}" placeholder="دقيقة"></label>`;return`<div class="exercise-tracker${done}" data-exercise="${esc(exercise)}" data-day="${dayIndex}" data-type="${type}"><div class="next-target">↗ ${progressionAdvice(exercise,type)}</div><div class="track-fields">${fields}<label>الإحساس<select name="difficulty"><option value="easy" ${current?.difficulty==='easy'?'selected':''}>سهل</option><option value="good" ${!current?.difficulty||current?.difficulty==='good'?'selected':''}>مناسب</option><option value="hard" ${current?.difficulty==='hard'?'selected':''}>صعب</option></select></label><button type="button">${current?.completed?'تم ✓':'حفظ الإنجاز'}</button></div></div>`}
function bindWorkoutTracking(target,program){if(target.id!=='memberProgram')return;target.querySelectorAll('.exercise-tracker button').forEach(button=>button.onclick=async()=>{const tracker=button.closest('.exercise-tracker'),type=tracker.dataset.type,exercise=tracker.dataset.exercise,dayIndex=Number(tracker.dataset.day),body={program_id:program.id,session_date:new Date().toISOString().slice(0,10),day_index:dayIndex,exercise_name:exercise,exercise_type:type,target_text:progressionAdvice(exercise,type),difficulty:tracker.querySelector('[name="difficulty"]').value,completed:true,weight_kg:type==='strength'?Number(tracker.querySelector('[name="weight"]').value)||null:null,reps:type==='strength'?Number(tracker.querySelector('[name="reps"]').value)||null:null,duration_minutes:type!=='strength'?Number(tracker.querySelector('[name="duration"]').value)||null:null};button.disabled=true;try{const saved=await StrongGymAPI.saveWorkoutLog(body),row=Array.isArray(saved)?saved[0]:saved;memberWorkoutLogs=memberWorkoutLogs.filter(log=>!(log.exercise_name===exercise&&Number(log.day_index)===dayIndex&&log.session_date===body.session_date));if(row)memberWorkoutLogs.unshift(row);showProgram(program,target);notify('تم حفظ الأداء وتحديث هدف الجلسة القادمة')}catch(error){button.disabled=false;notify(error.message,'error')}})}
function nutritionTargets(){return{calories:Number(currentMemberProgram?.daily_calories||2000),protein:Number(currentMemberProgram?.protein_g||110),water:Math.round(Number(currentMemberProgram?.water_liters||2.5)*1000)}}
function renderNutrition(){const live=document.getElementById('nutritionLive'),history=document.getElementById('mealHistory');if(!live||!history)return;const target=nutritionTargets(),used=memberMealLogs.reduce((sum,row)=>({calories:sum.calories+Number(row.calories||0),protein:sum.protein+Number(row.protein_g||0),water:sum.water+Number(row.water_ml||0)}),{calories:0,protein:0,water:0}),remaining={calories:Math.max(0,target.calories-used.calories),protein:Math.max(0,target.protein-used.protein),water:Math.max(0,target.water-used.water)},metric=(label,value,targetValue,unit,color)=>`<div><span>${label}</span><b>${Math.round(value)}<small>${unit}</small></b><div><i style="width:${Math.min(100,Math.round(value/Math.max(1,targetValue)*100))}%;background:${color}"></i></div><em>متبقي ${Math.round(Math.max(0,targetValue-value))}${unit}</em></div>`;live.innerHTML=`<div class="nutrition-metrics">${metric('السعرات',used.calories,target.calories,'','#ff9d16')}${metric('البروتين',used.protein,target.protein,'غ','#7ddc76')}${metric('الماء',used.water,target.water,'مل','#55afe3')}</div><p>هدف اليوم: ${target.calories} سعرة · ${target.protein}غ بروتين · ${(target.water/1000).toFixed(1)} لتر ماء</p>`;history.innerHTML=memberMealLogs.length?memberMealLogs.map(row=>`<article><div><b>${esc(row.meal_name)}</b><span>${row.calories} سعرة · ${row.protein_g}غ بروتين · ${row.water_ml}مل ماء</span></div><button type="button" data-delete-meal="${row.id}" aria-label="حذف الوجبة">×</button></article>`).join(''):'<div class="empty-state">لم تسجّل أي وجبة اليوم بعد.</div>';history.querySelectorAll('[data-delete-meal]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await StrongGymAPI.deleteMealLog(button.dataset.deleteMeal);memberMealLogs=memberMealLogs.filter(row=>row.id!==button.dataset.deleteMeal);renderNutrition();notify('تم حذف الوجبة')}catch(error){button.disabled=false;notify(error.message,'error')}})}
function showProgram(program,target=document.getElementById('programPreview')){if(!target)return;const goal={weight_loss:'نزول الوزن',muscle_gain:'زيادة الكتلة العضلية',fitness:'لياقة وصحة عامة',maintenance:'المحافظة على الوزن'}[program.goal]||'برنامج مخصص',carbs=program.carbs_g||'—',fats=program.fats_g||'—',tracking=target.id==='memberProgram';target.innerHTML=`${tracking?trackingOverview(program):''}<div class="program-summary nutrition-summary"><span>${goal}</span><div><b>${program.daily_calories}</b><small>سعرة</small></div><div><b>${program.protein_g}غ</b><small>بروتين</small></div><div><b>${program.water_liters}L</b><small>ماء</small></div><div><b>${carbs}غ</b><small>كربوهيدرات</small></div><div><b>${fats}غ</b><small>دهون</small></div></div><div class="program-section-head"><div><span>TRAIN SMART</span><h3 id="myProgram">جدول التمارين</h3></div><small>${program.training_days||program.workout_plan.length} أيام أسبوعيًا</small></div><div class="workout-days visual-days">${program.workout_plan.map((day,index)=>{const visual=exerciseVisual(day.focus,index);return`<section class="visual-workout"><div class="workout-cover"><img src="${visual[0]}" alt="${visual[1]}" loading="lazy"><span>${esc(day.day)}</span></div><div class="workout-body"><b>${esc(day.focus)}</b>${day.exercises.map((x,i)=>`<small class="exercise-item"><i class="exercise-thumb" style="${exerciseThumb(x)}" role="img" aria-label="صورة توضيحية: ${esc(x)}"></i><span><em>${String(i+1).padStart(2,'0')}</em>${esc(x)}</span></small>${tracking?trackingControls(x,index):''}`).join('')}</div></section>`}).join('')}</div><div class="program-section-head nutrition-head" id="myNutrition"><div><span>FUEL YOUR GOAL</span><h3>خطة الوجبات</h3></div><small>${program.daily_calories} سعرة يوميًا</small></div><div class="meal-list enhanced-meals">${program.meal_plan.map((m,i)=>`<p><i>${String(i+1).padStart(2,'0')}</i><b>${esc(m.name)}</b><span>${esc(m.items)}</span></p>`).join('')}</div>${program.notes?`<div class="program-note"><b>ملاحظات الكوتش:</b> ${esc(program.notes)}</div>`:''}<p class="medical-note">الخطة إرشادية وليست بديلًا عن الطبيب أو أخصائي التغذية، خصوصًا عند وجود حالة صحية.</p>`;if(tracking)bindWorkoutTracking(target,program)}

function openModal(name){const modal=document.getElementById(`${name}Modal`);if(modal){modal.hidden=false;document.body.classList.add('modal-open')}}function closeModals(){document.querySelectorAll('.modal-layer').forEach(m=>m.hidden=true);document.body.classList.remove('modal-open')}
document.querySelectorAll('[data-open-modal]').forEach(b=>b.onclick=()=>openModal(b.dataset.openModal));document.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModals);document.querySelectorAll('.modal-layer').forEach(m=>m.onclick=e=>{if(e.target===m)closeModals()});
function syncPaymentAmount(){const select=document.getElementById('paymentSubscription'),option=select?.selectedOptions[0];if(option)document.getElementById('paymentAmount').value=option.dataset.amount||''}document.getElementById('paymentSubscription')?.addEventListener('change',syncPaymentAmount);
document.getElementById('paymentForm')?.addEventListener('submit',async e=>{e.preventDefault();const id=document.getElementById('paymentSubscription').value,amount=document.getElementById('paymentAmount').value;if(!id)return notify('لا يوجد اشتراك بانتظار الدفع','error');const button=e.submitter;button.disabled=true;try{await StrongGymAPI.activateCash(id,amount,document.getElementById('paymentNote').value);closeModals();notify('تم تأكيد الدفعة وتفعيل الاشتراك من اليوم');await refreshAdmin()}catch(error){notify(error.message,'error')}finally{button.disabled=false}});
document.getElementById('measurementForm')?.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.currentTarget),values={member_id:document.getElementById('measurementMember').value};for(const [key,value] of data)if(value!=='')values[key]=Number(value);const button=e.submitter;button.disabled=true;try{await StrongGymAPI.addMeasurement(values);e.currentTarget.reset();closeModals();notify('تم حفظ القياسات الجديدة');await refreshAdmin();goView('measurements')}catch(error){notify(error.message,'error')}finally{button.disabled=false}});
document.getElementById('programForm')?.addEventListener('submit',async e=>{e.preventDefault();const memberId=document.getElementById('programMember').value;if(!memberId)return notify('اختر المشترك أولًا','error');const program=buildProgram(memberId,document.getElementById('programGoal').value,document.getElementById('programDays').value,document.getElementById('programNotes').value.trim()),button=e.submitter;button.disabled=true;showProgram(program);try{await StrongGymAPI.saveProgram(program);notify('تم إنشاء البرنامج وحفظه في حساب المشترك');await refreshAdmin()}catch(error){notify(error.message,'error')}finally{button.disabled=false}});
document.getElementById('memberSearch')?.addEventListener('input',renderMembers);document.querySelectorAll('[data-member-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-member-filter]').forEach(x=>x.classList.toggle('active',x===b));memberFilter=b.dataset.memberFilter;renderMembers()});
document.querySelectorAll('[data-segment]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-segment]').forEach(x=>x.classList.toggle('active',x===b));const selected=b.dataset.segment;document.querySelectorAll('[data-gender]').forEach(x=>x.classList.toggle('is-hidden',selected!=='all'&&x.dataset.gender!==selected))});
async function refreshAdmin(){adminStore=await StrongGymAPI.adminData();renderAll();updateBackupStatus();const label=document.getElementById('todayLabel');if(label)label.textContent=new Intl.DateTimeFormat('ar-PS',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date())+' · بيانات محدثة مباشرة';const last=Number(localStorage.getItem(backupStorageKey)||0);if(!last||Date.now()-last>=7*864e5)setTimeout(()=>notify('حان موعد النسخة الاحتياطية الأسبوعية. نزّلها من الإعدادات.'),900)}
function hydrateMember(data,program){const sub=data.subscriptions.find(s=>s.member_id===currentProfile.id&&s.status==='active')||data.subscriptions.find(s=>s.member_id===currentProfile.id),plan=sub&&data.plans.find(p=>String(p.id)===String(sub.plan_id)),hero=document.getElementById('memberSubscription');if(hero){const remaining=sub?.ends_on?Math.max(0,Math.ceil((new Date(sub.ends_on)-new Date())/864e5)+1):0,percent=sub?.starts_on&&sub?.ends_on?Math.max(0,Math.min(100,Math.round((Date.now()-new Date(sub.starts_on))/(new Date(sub.ends_on)-new Date(sub.starts_on))*100))):0;hero.querySelector('.badge').className=`badge ${sub?.status||'pending'}`;hero.querySelector('.badge').textContent=statusLabel[sub?.status]||'بانتظار التفعيل';hero.querySelector('h2').textContent=sub?.status==='active'?`باقي ${remaining} يوم`:'الاشتراك بانتظار الدفع';hero.querySelector('p').textContent=plan?`${plan.name_ar} · ${sub?.ends_on?`فعال حتى ${date(sub.ends_on)}`:'يبدأ بعد تأكيد الدفعة'}`:'تواصل مع الإدارة لاستكمال الاشتراك.';hero.querySelector('.membership-ring strong').textContent=`${percent}%`}const latest=data.measurements.find(m=>m.member_id===currentProfile.id),box=document.getElementById('memberMeasurements');if(latest)box.innerHTML=`<div class="measurement-summary"><div><b>${latest.weight_kg}</b><small>كغ وزن</small></div><div><b>${latest.height_cm}</b><small>سم طول</small></div><div><b>${latest.waist_cm||'—'}</b><small>سم خصر</small></div><div><b>${date(latest.recorded_at)}</b><small>آخر تحديث</small></div></div>`;if(program){const area=document.getElementById('memberProgramArea');area.innerHTML='<article class="card program-preview" id="memberProgram"></article>';showProgram(program,document.getElementById('memberProgram'))}}
function hydrateHealth(health){memberHealth=health;const account=document.getElementById('accountForm');if(account&&currentProfile){account.elements.full_name.value=currentProfile.full_name||'';account.elements.whatsapp_e164.value=currentProfile.whatsapp_e164||''}const form=document.getElementById('healthForm');if(!form||!health)return;form.elements.birth_date.value=health.birth_date||'';form.elements.activity_level.value=health.activity_level||'moderate';form.elements.goal.value=health.goal||'fitness';form.elements.medical_notes.value=health.medical_notes||'';if(health.birth_date){const born=new Date(`${health.birth_date}T00:00:00`),today=new Date();let age=today.getFullYear()-born.getFullYear();if(today<new Date(today.getFullYear(),born.getMonth(),born.getDate()))age--;const ageInput=document.getElementById('a');if(ageInput&&age>0)ageInput.value=age}}
async function connectAccount(){if(!window.StrongGymAPI)throw new Error('تعذر تحميل الاتصال الآمن');currentProfile=await StrongGymAPI.profile();if(!currentProfile||currentProfile.status!=='active'){location.replace('index.html?login=1');return}const adminPage=location.pathname.toLowerCase().includes('admin');if(adminPage&&!['manager','coach'].includes(currentProfile.role)){location.replace('member.html');return}document.querySelectorAll('.person b').forEach(el=>el.textContent=currentProfile.full_name);await loadNotifications();if(adminPage){await refreshAdmin();goView(location.hash.slice(1)||'overview',false)}else{document.querySelector('.top h1').textContent=`أهلاً ${currentProfile.full_name} 👋`;if(currentProfile.gender!=='female')document.querySelectorAll('a[href*="chat.whatsapp.com"]').forEach(a=>a.remove());const [data,program,health,meals]=await Promise.all([StrongGymAPI.adminData(),StrongGymAPI.memberProgram(),StrongGymAPI.healthProfile(),StrongGymAPI.mealLogs()]);currentMemberProgram=program;memberMealLogs=meals;memberWorkoutLogs=program?await StrongGymAPI.workoutLogs(program.id):[];hydrateMember(data,program);hydrateHealth(health);renderNutrition()}}
document.getElementById('logoutBtn')?.addEventListener('click',async()=>{await StrongGymAPI.signOut();location.replace('index.html')});
document.getElementById('mealEntry')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=event.submitter,data=new FormData(form),body={logged_on:new Date().toISOString().slice(0,10),meal_name:data.get('meal_name').trim(),calories:Number(data.get('calories')),protein_g:Number(data.get('protein_g')||0),water_ml:Number(data.get('water_ml')||0)};button.disabled=true;try{const saved=await StrongGymAPI.addMealLog(body),row=Array.isArray(saved)?saved[0]:saved;if(row)memberMealLogs.unshift(row);form.reset();form.elements.protein_g.value=0;form.elements.water_ml.value=0;renderNutrition();notify('تمت إضافة الوجبة وتحديث المتبقي')}catch(error){notify(error.message,'error')}finally{button.disabled=false}});
connectAccount().catch(error=>{notify(error.message,'error');setTimeout(()=>location.replace('index.html?login=1'),1800)});
